{
  "aggregate": {{ this.params.collection }},
  "pipeline": {{
    (() => {
      const includeIds = this.params.includeIds || [];

      const pipeline = [];

      // GEZIELTER EINSCHLUSS VON IDs (String-Array)
      if (Array.isArray(includeIds) && includeIds.length > 0) {
        const validIncludeIds = includeIds
          .filter(id => id && /^[0-9a-fA-F]{24}$/.test(String(id)))
          .map(id => String(id));

        if (validIncludeIds.length > 0) {
          pipeline.push({
            "$match": {
              "$expr": {
                "$in": [
                  { "$toString": "$_id" },
                  validIncludeIds
                ]
              }
            }
          });
        }
      }

      pipeline.push(
        {
          "$lookup": {
            "from": "master_answer",
            "localField": "_id",
            "foreignField": "question_id",
            "as": "answers"
          }
        }
      );

      return pipeline;
    })()
  }},
  "cursor": {
    "batchSize": {{ Math.max(1, (this.params.includeIds || []).length || 10) }}
  }
}
